    pattern2 = re.compile(r'(?i)\b(?:[a-z0-9-]+\.)+[a-z]{2,}(?:/[^\s<>()\[\]{}"\'`]*)?')

    trailing_trim = '.,;:!?)]}\'"'
    leading_chars = set('([{\'"')

    def clean_match(s):
