        # Trim leading punctuation like opening parentheses or quotes
        while s and s[0] in leading_chars:
            s = s[1:]
        return s

    def is_valid_url(s):
        # For validation, ensure there is a network location after parsing.
        # If there's no scheme, prepend http:// for parsing purposes.
        parse_target = s
        if not re.match(r'(?i)^[a-z][a-z0-9+\-.]*://', s):
            parse_target = 'http://' + s
        try:
            parsed = urlparse(parse_target)
        except Exception:
            return False
        if not parsed.netloc:
            return False
        hostname = parsed.hostname or ''
        if hostname == '':
            return False
        if hostname == 'localhost' or '.' in hostname:
            return True
        return False

    first_url_candidate = None
    for pattern in (pattern1, pattern2):
        for m in pattern.finditer(myString):
            candidate = m.group(0)
            candidate = clean_match(candidate)
            if not candidate:
                continue
            if is_valid_url(candidate):
                first_url_candidate = candidate
                break
        if first_url_candidate:
