    if not first_url_candidate:
        return "{URL} not found"

    # Prepare URL for fetching: ensure scheme
    fetch_url = first_url_candidate
    if not re.match(r'(?i)^[a-z][a-z0-9+\-.]*://', fetch_url):
        fetch_url = 'http://' + fetch_url

    # Perform HTTP GET
    try:
        req = Request(fetch_url, headers={'User-Agent': 'Mozilla/5.0 (compatible; URLFetcher/1.0)'})
        with urlopen(req, timeout=10) as resp:
            data = resp.read()
            # Try to determine charset
            charset = None
            try:
                # http.client.HTTPResponse.headers is an email.message.Message with get_content_charset
                charset = resp.headers.get_content_charset()  # may return None
            except Exception:
                charset = None
            if not charset:
                ct = resp.headers.get('Content-Type', '') or ''
                m = re.search(r'charset=([^\s;]+)', ct, re.I)
                if m:
                    charset = m.group(1).strip(' "\'')
            if not charset:
                charset = 'utf-8'
            try:
                text = data.decode(charset, errors='replace')
            except Exception:
                text = data.decode('utf-8', errors='replace')
            return text
    except (HTTPError, URLError, ValueError, Exception):
        return "{URL} could not be fetched."

