import java.util.*;

class GraphAnalyzer {

    /**
     * Computes the shortest distances from the source vertex to all other vertices
     * in a weighted graph represented by an adjacency matrix using Dijkstra's algorithm.
     *
     * @param graph  adjacency matrix where graph[u][v] is the weight of the edge u→v
     *               (0 indicates no edge). The matrix must be square.
     * @param source the index of the source vertex
     * @return a map containing:
     *         - "distances": int[] of shortest distances from source
     *         - "paths": List<List<Integer>> where each inner list is the sequence of
     *           vertices from source to the corresponding vertex
     */
    public static Map<String, Object> analyzeGraph(int[][] graph, int source) {
        int n = graph.length;
        int[] dist = new int[n];
        int[] prev = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        Arrays.fill(prev, -1);
        dist[source] = 0;

        PriorityQueue<Vertex> pq = new PriorityQueue<>(Comparator.comparingInt(v -> v.distance));
        pq.add(new Vertex(source, 0));

        while (!pq.isEmpty()) {
            Vertex current = pq.poll();
            int u = current.index;

            // Skip stale entries
            if (current.distance != dist[u]) {
                continue;
            }

            for (int v = 0; v < n; v++) {
                int weight = graph[u][v];
                if (weight > 0) { // edge exists
                    int alt = dist[u] + weight;
                    if (alt < dist[v]) {
                        dist[v] = alt;
                        prev[v] = u;
                        pq.add(new Vertex(v, alt));
                    }
                }
            }
        }

        // Reconstruct paths
        List<List<Integer>> paths = new ArrayList<>(n);
        for (int target = 0; target < n; target++) {
            paths.add(buildPath(prev, source, target));
        }

        Map<String, Object> result = new HashMap<>();
        result.put("distances", dist);
        result.put("paths", paths);
        return result;
    }

    /**
     * Reconstructs the shortest path from source to target using the predecessor array.
     *
     * @param prev   array where prev[v] is the predecessor of v on the shortest path
     * @param source the source vertex
     * @param target the target vertex
     * @return a list of vertex indices representing the path from source to target.
     *         If the target is unreachable, returns an empty list.
     */
    private static List<Integer> buildPath(int[] prev, int source, int target) {
        List<Integer> path = new ArrayList<>();
        if (target == source) {
            path.add(source);
            return path;
        }
        if (prev[target] == -1) {
            // Unreachable
            return path;
        }
        int current = target;
        while (current != -1) {
            path.add(current);
            if (current == source) {
                break;
            }
            current = prev[current];
        }
        Collections.reverse(path);
        // Verify that the path starts with the source
        if (path.isEmpty() || path.get(0) != source) {
            return new ArrayList<>();
        }
        return path;
    }

    /**
     * Helper class representing a vertex in the priority queue.
     */
    private static class Vertex {
        int index;
        int distance;

        Vertex(int index, int distance) {
            this.index = index;
            this.distance = distance;
        }
    }
}

