        // Simple 3-vertex graph: 0 -> 1 (weight 4), 0 -> 2 (weight 2), 1 -> 2 (weight 1)
        int[][] graph = {
            {0, 4, 2},
            {0, 0, 1},
            {0, 0, 0}
        };

        Map<String, Object> result = GraphAnalyzer.analyzeGraph(graph, 0);

        // Check distances
        List<Integer> distances = (List<Integer>) result.get("distances");
        assertEquals(0, distances.get(0)); // Distance to source is 0
        assertEquals(4, distances.get(1)); // Distance to vertex 1
        assertEquals(2, distances.get(2)); // Distance to vertex 2

        // Check paths
        Map<Integer, List<Integer>> paths = (Map<Integer, List<Integer>>) result.get("paths");
        assertEquals(Arrays.asList(0), paths.get(0)); // Path to source
        assertEquals(Arrays.asList(0, 1), paths.get(1)); // Path to vertex 1
        assertEquals(Arrays.asList(0, 2), paths.get(2)); // Path to vertex 2
    }

