        shipPositions.addAll(coordinates);
    }

    /**
     * Records an attack at the given coordinate and reports the result.
     *
     * @param coordinate board coordinate being attacked
     * @return {@link HitResult#HIT} if a ship occupies the coordinate,
     *         {@link HitResult#MISS} if no ship occupies the coordinate,
     *         {@link HitResult#SUNK} if this hit destroys the last remaining ship part
     * @throws IllegalArgumentException if {@code coordinate} is {@code null} or empty
     */
    public HitResult receiveAttack(String coordinate) {
        if (coordinate == null || coordinate.isEmpty()) {
            throw new IllegalArgumentException("Attack coordinate must not be null or empty.");
        }

        attackPositions.add(coordinate);

        if (shipPositions.contains(coordinate)) {
            // Remove the hit part of the ship.
            shipPositions.remove(coordinate);
            // If no ship parts remain, the fleet is sunk → game over.
            if (shipPositions.isEmpty()) {
                gameOver = true;
                winner = "Opponent";
                return HitResult.SUNK;
            }
            return HitResult.HIT;
        }

        return HitResult.MISS;
    }

    /**
     * Returns a snapshot of the current game state.
     *
     * @return a {@link GameState} object containing remaining ships, attacks made,
     *         game‑over flag and winner name
     */
    public GameState getGameState() {
        return new GameState(
                shipPositions.size(),
                attackPositions.size(),
                gameOver,
                winner
        );
    }

    /** Returns an unmodifiable view of the ship positions (useful for testing). */
    public Set<String> getShipPositions() {
        return Collections.unmodifiableSet(shipPositions);
    }

    /** Returns an unmodifiable view of the attack positions (useful for testing). */
    public Set<String> getAttackPositions() {
        return Collections.unmodifiableSet(attackPositions);
    }

    /** Result of an attack. */
    public enum HitResult {
        HIT,
        MISS,
        SUNK
    }

    /**
     * Immutable data holder describing the current state of the game.
     */
    public static final class GameState {
        private final int remainingShips;
        private final int attacksMade;
        private final boolean gameOver;
        private final String winner;

        public GameState(int remainingShips, int attacksMade, boolean gameOver, String winner) {
            this.remainingShips = remainingShips;
            this.attacksMade = attacksMade;
            this.gameOver = gameOver;
            this.winner = winner;
        }

        /** Number of ship positions that have not yet been hit. */
        public int getRemainingShips() {
            return remainingShips;
        }

        /** Total number of attacks that have been performed. */
        public int getAttacksMade() {
            return attacksMade;
        }

        /** Whether the game has finished. */
        public boolean isGameOver() {
            return gameOver;
        }

        /** Name of the winner, or {@code null} if the game is not over. */
        public String getWinner() {
            return winner;
        }

        @Override
        public String toString() {
            return "GameState{" +
                    "remainingShips=" + remainingShips +
                    ", attacksMade=" + attacksMade +
                    ", gameOver=" + gameOver +
                    ", winner='" + winner + '\'' +
                    '}';
        }
    }
}

