/***************************************************************************************************
 *  Graph implementation with a parallel, scored edge‑promotion strategy for node deletion.
 *
 *  When a node is marked for deletion we:
 *   1. Remove all its incident edges.
 *   2. Promote edges among its former neighbours using a scoring function (the “FreshDiskANN”
 *      edge‑promotion strategy).  For every unordered pair (i, k) of neighbours we compute a
 *      score and keep the highest‑scoring candidates.
 *   3. Add the promoted edges until each former neighbour reaches the desired degree
 *      (TARGET_DEGREE).  If a neighbour still lacks enough edges we fall back to adding random
 *      valid edges so that the graph stays connected.
 *
 *  All heavy work is performed with parallel streams; the underlying collections are
 *  concurrent, guaranteeing thread‑safety without explicit synchronisation.
 **************************************************************************************************/

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.*;
import java.util.stream.*;

public class Graph {

    /** --------------------------------------------------------------------- */
    /** Core data structures                                                   */
    /** --------------------------------------------------------------------- */

    /** adjacency list: node id → concurrent set of neighbour ids */
    private final ConcurrentMap<Integer, ConcurrentSkipListSet<Integer>> adjacency = new ConcurrentHashMap<>();

    /** nodes that have been marked for deletion (concurrent) */
    private final Set<Integer> deletedNodes = ConcurrentHashMap.newKeySet();

    /** Desired degree for every node after deletions (can be tuned) */
    private static final int TARGET_DEGREE = 5;

    /** Random generator for fallback edge creation */
    private static final ThreadLocalRandom RAND = ThreadLocalRandom.current();

    /** --------------------------------------------------------------------- */
    /** Helper methods                                                         */
    /** --------------------------------------------------------------------- */

    /** Adds an undirected edge (u,v). */
    public void addEdge(int u, int v) {
        if (u == v) return;                     // ignore self‑loops
        adjacency.computeIfAbsent(u, k -> new ConcurrentSkipListSet<>()).add(v);
        adjacency.computeIfAbsent(v, k -> new ConcurrentSkipListSet<>()).add(u);
    }

    /** Returns a snapshot of the neighbour set of {@code node}. */
    public Set<Integer> neighbours(int node) {
        return adjacency.getOrDefault(node, new ConcurrentSkipListSet<>());
    }

    /** Marks {@code node} for deletion. */
    public void markDeleted(int node) {
        deletedNodes.add(node);
    }

    /** Returns true if {@code node} currently exists in the graph. */
    public boolean containsNode(int node) {
        return adjacency.containsKey(node);
    }

    /** Returns a collection view of all node identifiers currently present. */
    public Collection<Integer> allNodeIds() {
        return adjacency.keySet();
    }

    /** --------------------------------------------------------------------- */
    /** Scoring infrastructure                                                 */
    /** --------------------------------------------------------------------- */

    /** Functional interface for scoring a potential edge (src, dst). */
    @FunctionalInterface
    public interface EdgeScorer {
        /** Higher values indicate a more desirable edge. */
        double score(int src, int dst);
    }

    /** Default scorer – prefers edges that connect nodes with similar degree
     *  (the smaller the absolute degree difference, the higher the score). */
    private final EdgeScorer defaultScorer = (src, dst) -> {
        int degSrc = adjacency.getOrDefault(src, new ConcurrentSkipListSet<>()).size();
        int degDst = adjacency.getOrDefault(dst, new ConcurrentSkipListSet<>()).size();
        // Inverse of degree difference + 1 to avoid division by zero.
        return 1.0 / (Math.abs(degSrc - degDst) + 1);
    };

    /** --------------------------------------------------------------------- */
    /** Core method – removeDeletedNodes with scored edge promotion           */
    /** --------------------------------------------------------------------- */

    /**
     * Removes all nodes that have been marked for deletion.
     *
     * <p>For each deleted node {@code j} we:
     *   <ol>
     *     <li>Collect its neighbours {@code N(j)}.</li>
     *     <li>Remove all edges incident to {@code j}.</li>
     *     <li>Generate candidate edges between every unordered pair of {@code N(j)}.</li>
     *     <li>Score each candidate with {@link #defaultScorer} and keep the highest‑scoring
     *         ones, adding them until each node in {@code N(j)} reaches {@link #TARGET_DEGREE}
     *         neighbours.</li>
     *     <li>If a node still lacks neighbours, add random valid edges to keep the graph
     *         connected.</li>
     *   </ol>
     *
     * <p>The whole process is executed in parallel using Java streams.
     *
     * @return the number of nodes that were removed
     */
    public long removeDeletedNodes() {
        AtomicLong removedCount = new AtomicLong(0L);

        // Process each deleted node in parallel.
        deletedNodes.parallelStream().forEach(deletedNode -> {
            // -----------------------------------------------------------------
            // 1) Snapshot of neighbours before we delete anything.
            // -----------------------------------------------------------------
            Set<Integer> neighbourSnapshot = new HashSet<>(neighbours(deletedNode));

            // -----------------------------------------------------------------
            // 2) Remove all edges that point to the deleted node.
            // -----------------------------------------------------------------
            neighbourSnapshot.forEach(nb -> {
                ConcurrentSkipListSet<Integer> set = adjacency.get(nb);
                if (set != null) {
                    set.remove(deletedNode);
                }
            });

            // -----------------------------------------------------------------
            // 3) Delete the node itself.
            // -----------------------------------------------------------------
            adjacency.remove(deletedNode);

            // -----------------------------------------------------------------
            // 4) Edge promotion with scoring.
            // -----------------------------------------------------------------
            List<Integer> neighbourList = new ArrayList<>(neighbourSnapshot);
            int n = neighbourList.size();

            // Build candidate edges with scores (parallel over first index).
            List<CandidateEdge> candidates = IntStream.range(0, n)
                    .parallel()
                    .mapToObj(iIdx -> {
                        int i = neighbourList.get(iIdx);
                        List<CandidateEdge> local = new ArrayList<>();
                        for (int kIdx = iIdx + 1; kIdx < n; kIdx++) {
                            int k = neighbourList.get(kIdx);
                            // Skip if edge already exists.
                            if (adjacency.getOrDefault(i, new ConcurrentSkipListSet<>()).contains(k)) {
                                continue;
                            }
                            double sc = defaultScorer.score(i, k);
                            local.add(new CandidateEdge(i, k, sc));
                        }
                        return local;
                    })
                    .flatMap(Collection::stream)
                    .collect(Collectors.toList());

            // Sort candidates by descending score.
            candidates.sort(Comparator.comparingDouble((CandidateEdge ce) -> ce.score).reversed());

            // Track which neighbours still need edges.
            Set<Integer> stillNeeding = neighbourList.stream()
                    .filter(v -> adjacency.getOrDefault(v, new ConcurrentSkipListSet<>()).size() < TARGET_DEGREE)
                    .collect(Collectors.toSet());

            // Add promoted edges while we have candidates and nodes still need neighbours.
            for (CandidateEdge ce : candidates) {
                if (stillNeeding.isEmpty()) break;

                // Both ends must still need neighbours to be useful.
                boolean iNeed = stillNeeding.contains(ce.src);
                boolean kNeed = stillNeeding.contains(ce.dst);
                if (!iNeed && !kNeed) continue;

                addEdge(ce.src, ce.dst);

                // Update the need‑set.
                if (adjacency.get(ce.src).size() >= TARGET_DEGREE) stillNeeding.remove(ce.src);
                if (adjacency.get(ce.dst).size() >= TARGET_DEGREE) stillNeeding.remove(ce.dst);
            }

            // -----------------------------------------------------------------
            // 5) Random fallback edges for any remaining deficient nodes.
            // -----------------------------------------------------------------
            List<Integer> allNodes = new ArrayList<>(allNodeIds()); // snapshot for random picks
            for (int deficient : stillNeeding) {
                while (adjacency.getOrDefault(deficient, new ConcurrentSkipListSet<>()).size() < TARGET_DEGREE) {
                    // Pick a random node that is not the same and not already a neighbour.
                    int randomNode = allNodes.get(RAND.nextInt(allNodes.size()));
                    if (randomNode == deficient) continue;
                    if (adjacency.getOrDefault(deficient, new ConcurrentSkipListSet<>()).contains(randomNode))
                        continue;
                    addEdge(deficient, randomNode);
                }
            }

            // -----------------------------------------------------------------
            // 6) Count this deletion.
            // -----------------------------------------------------------------
            removedCount.incrementAndGet();
        });

        // All deletions processed – clear the deletion set.
        deletedNodes.clear();

        return removedCount.get();
    }

    /** Simple holder for a candidate edge together with its score. */
    private static final class CandidateEdge {
        final int src;
        final int dst;
        final double score;

        CandidateEdge(int src, int dst, double score) {
            this.src = src;
            this.dst = dst;
            this.score = score;
        }
    }

    /** --------------------------------------------------------------------- */
    /** Example usage (not part of the required answer)                       */
    /** --------------------------------------------------------------------- */
    public static void main(String[] args) {
        Graph g = new Graph();

        // Build a small example graph.
        g.addEdge(0, 1);
        g.addEdge(1, 2);
        g.addEdge(2, 3);
        g.addEdge(3, 4);
        g.addEdge(4, 0);
        g.addEdge(1, 3);
        g.addEdge(2, 4);

        // Mark node 2 for deletion.
        g.markDeleted(2);

        System.out.println("Before removal:");
        g.adjacency.forEach((n, nb) -> System.out.println(n + " -> " + nb));

        long removed = g.removeDeletedNodes();
        System.out.println("\nRemoved nodes: " + removed);

        System.out.println("\nAfter removal (edges promoted with scoring, random fallback if needed):");
        g.adjacency.forEach((n, nb) -> System.out.println(n + " -> " + nb));
    }
}

