import org.junit.jupiter.api.Test;
import java.util.*;

class TestRedditFeedAnalyzer {

    @Test
    void testNoItemsMeetMinimumScoreRequirement() {
        RedditFeedAnalyzer analyzer = new RedditFeedAnalyzer();
        List<RedditFeedItem> feedItems = new ArrayList<>();
        feedItems.add(new RedditFeedItem("Title1", "url1", "sub1", "domain1", "id1", "author1", 5, "thumb1", "link1", 1000L, 10));
        feedItems.add(new RedditFeedItem("Title2", "url2", "sub2", "domain2", "id2", "author2", 3, "thumb2", "link2", 2000L, 5));

        String result = analyzer.analyzeAndFormatFeed(feedItems, 10);
        assertEquals("No items meet the minimum score requirement of 10", result);
    }

    @Test
    void testEmptyList() {
        RedditFeedAnalyzer analyzer = new RedditFeedAnalyzer();
        List<RedditFeedItem> feedItems = new ArrayList<>();

        String result = analyzer.analyzeAndFormatFeed(feedItems, 5);
        assertEquals("No feed items to analyze", result);
    }

    @Test
    void testNullList() {
        RedditFeedAnalyzer analyzer = new RedditFeedAnalyzer();

        String result = analyzer.analyzeAndFormatFeed(null, 5);
        assertEquals("No feed items to analyze", result);
    }

    @Test
    void testFormattingWithItemsMeetingThreshold() {
        RedditFeedAnalyzer analyzer = new RedditFeedAnalyzer();
        List<RedditFeedItem> feedItems = new ArrayList<>();
        feedItems.add(new RedditFeedItem("High Score Post", "url1", "sub1", "domain1", "id1", "author1", 100, "thumb1", "link1", 1000L, 50));
        feedItems.add(new RedditFeedItem("Medium Score Post", "url2", "sub2", "domain2", "id2", "author2", 50, "thumb2", "link2", 2000L, 20));
        feedItems.add(new RedditFeedItem("Low Score Post", "url3", "sub3", "domain3", "id3", "author3", 10, "thumb3", "link3", 3000L, 5));

        String result = analyzer.analyzeAndFormatFeed(feedItems, 5);
        String expected = "Feed Analysis Summary:\n" +
                         "Total items: 3\n" +
                         "Average score: 53.33\n" +
                         "Average comments: 25.00\n" +
                         "Top 3 items by score:\n" +
                         "1. High Score Post (Score: 100, Comments: 50)\n" +
                         "2. Medium Score Post (Score: 50, Comments: 20)\n" +
                         "3. Low Score Post (Score: 10, Comments: 5)";
        assertEquals(expected, result);
    }

    @Test
    void testFormattingWithOnlyOneItemMeetingThreshold() {
        RedditFeedAnalyzer analyzer = new RedditFeedAnalyzer();
        List<RedditFeedItem> feedItems = new ArrayList<>();
        feedItems.add(new RedditFeedItem("High Score Post", "url1", "sub1", "domain1", "id1", "author1", 100, "thumb1", "link1", 1000L, 50));
        feedItems.add(new RedditFeedItem("Low Score Post", "url2", "sub2", "domain2", "id2", "author2", 3, "thumb2", "link2", 2000L, 5));

        String result = analyzer.analyzeAndFormatFeed(feedItems, 50);
        String expected = "Feed Analysis Summary:\n" +
                         "Total items: 1\n" +
                         "Average score: 100.00\n" +
                         "Average comments: 50.00\n" +
                         "Top 3 items by score:\n" +
                         "1. High Score Post (Score: 100, Comments: 50)";
        assertEquals(expected, result);
    }

    @Test
    void testExactFormattingWithNewlinesAndSpacing() {
        RedditFeedAnalyzer analyzer = new RedditFeedAnalyzer();
        List<RedditFeedItem> feedItems = new ArrayList<>();
        feedItems.add(new RedditFeedItem("Test Post", "url1", "sub1", "domain1", "id1", "author1", 25, "thumb1", "link1", 1000L, 15));

        String result = analyzer.analyzeAndFormatFeed(feedItems, 20);
        String expected = "Feed Analysis Summary:\n" +
                         "Total items: 1\n" +
                         "Average score: 25.00\n" +
                         "Average comments: 15.00\n" +
                         "Top 3 items by score:\n" +
                         "1. Test Post (Score: 25, Comments: 15)";

        // Verify exact string match including newlines
        assertEquals(expected, result);

        // Additional verification that result contains exactly the right number of newlines
        long newlineCount = result.chars().filter(ch -> ch == '\n').count();
        assertEquals(5, newlineCount); // 5 newlines in the expected format
    }
}

