def parse_tweets(raw_tweets, source, now=None):
    tweets = []
    for line in raw_tweets:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        try:
            parts = line.split('\t', 1)
            if len(parts) < 2:
                parts = line.split(' ', 1)
