import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

public class EnhancedFactory {
    private final AtomicInteger inputStock;
    private final AtomicInteger intermediateStock;
    private final AtomicInteger outputStock;
    private final int totalItemsToProcess;
    private final int version;
    private final Object stockLock = new Object();

    // Performance tracking
    private final AtomicLong startTime = new AtomicLong(0);
    private final AtomicLong endTime = new AtomicLong(0);
    private final AtomicInteger processedItems = new AtomicInteger(0);
    private final AtomicInteger errorCount = new AtomicInteger(0);

    public EnhancedFactory(int initialInputStock, int itemsToProcess, int version) {
        this.inputStock = new AtomicInteger(initialInputStock);
        this.intermediateStock = new AtomicInteger(0);
        this.outputStock = new AtomicInteger(0);
        this.totalItemsToProcess = itemsToProcess;
        this.version = version;

        if (version < 1 || version > 4) {
            throw new IllegalArgumentException("Version must be between 1 and 4");
        }
    }

    public FactoryPerformance runSimulation() {
        startTime.set(System.currentTimeMillis());

        switch (version) {
            case 1:
                processVersion1();
                break;
            case 2:
                processVersion2();
                break;
            case 3:
                processVersion3();
                break;
            case 4:
                processVersion4();
                break;
        }

        endTime.set(System.currentTimeMillis());

        return new FactoryPerformance(
            version,
            endTime.get() - startTime.get(),
            processedItems.get(),
            errorCount.get(),
            inputStock.get(),
            intermediateStock.get(),
            outputStock.get(),
            totalItemsToProcess
        );
    }

    private synchronized boolean takeFromInputStock(int count) {
        if (inputStock.get() >= count) {
            inputStock.addAndGet(-count);
            return true;
        }
        errorCount.incrementAndGet();
        return false;
    }

    private synchronized boolean addToIntermediateStock(int count) {
        intermediateStock.addAndGet(count);
        return true;
    }

    private synchronized boolean takeFromIntermediateStock(int count) {
        if (intermediateStock.get() >= count) {
            intermediateStock.addAndGet(-count);
            return true;
        }
        errorCount.incrementAndGet();
        return false;
    }

    private synchronized boolean addToOutputStock(int count) {
        if (outputStock.get() + count <= totalItemsToProcess) {
            outputStock.addAndGet(count);
            processedItems.addAndGet(count);
            return true;
        }
        errorCount.incrementAndGet();
        return false;
    }

    private void processVersion1() {
        Thread workshop = new Thread(() -> {
            while (processedItems.get() < totalItemsToProcess) {
                synchronized (stockLock) {
                    if (inputStock.get() > 0) {
                        if (takeFromInputStock(1) && addToOutputStock(1)) {
                            // Successfully processed
                        }
                    } else {
                        break;
                    }
                }
                try {
                    Thread.sleep(10);
                } catch (InterruptedException e) {
                    errorCount.incrementAndGet();
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        workshop.start();
        try {
            workshop.join();
        } catch (InterruptedException e) {
            errorCount.incrementAndGet();
            Thread.currentThread().interrupt();
        }
    }

    private void processVersion2() {
        Thread[] workshops = new Thread[2];

        for (int i = 0; i < workshops.length; i++) {
            workshops[i] = new Thread(() -> {
                while (processedItems.get() < totalItemsToProcess) {
                    synchronized (stockLock) {
                        if (inputStock.get() > 0) {
                            if (takeFromInputStock(1) && addToOutputStock(1)) {
                                // Successfully processed
                            }
                        } else {
                            break;
                        }
                    }
                    try {
                        Thread.sleep(15);
                    } catch (InterruptedException e) {
                        errorCount.incrementAndGet();
                        Thread.currentThread().interrupt();
                        break;
                    }
                }
            });
        }

        for (Thread workshop : workshops) {
            workshop.start();
        }

        for (Thread workshop : workshops) {
            try {
                workshop.join();
            } catch (InterruptedException e) {
                errorCount.incrementAndGet();
                Thread.currentThread().interrupt();
            }
        }
    }

    private void processVersion3() {
        Thread workshop1 = new Thread(() -> {
            while (processedItems.get() < totalItemsToProcess) {
                synchronized (stockLock) {
                    if (inputStock.get() > 0 && intermediateStock.get() < totalItemsToProcess) {
                        if (takeFromInputStock(1) && addToIntermediateStock(1)) {
                            // First processing step complete
                        }
                    }
                }
                try {
                    Thread.sleep(5);
                } catch (InterruptedException e) {
                    errorCount.incrementAndGet();
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        Thread workshop2 = new Thread(() -> {
            while (processedItems.get() < totalItemsToProcess) {
                synchronized (stockLock) {
                    if (intermediateStock.get() > 0) {
                        if (takeFromIntermediateStock(1) && addToIntermediateStock(1)) {
                            // Second processing step complete
                        }
                    }
                }
                try {
                    Thread.sleep(5);
                } catch (InterruptedException e) {
                    errorCount.incrementAndGet();
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        Thread workshop3 = new Thread(() -> {
            while (processedItems.get() < totalItemsToProcess) {
                synchronized (stockLock) {
                    if (intermediateStock.get() > 0) {
                        if (takeFromIntermediateStock(1) && addToOutputStock(1)) {
                            // Final processing step complete
                        }
                    }
                }
                try {
                    Thread.sleep(5);
                } catch (InterruptedException e) {
                    errorCount.incrementAndGet();
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        workshop1.start();
        workshop2.start();
        workshop3.start();

        try {
            workshop1.join();
            workshop2.join();
            workshop3.join();
        } catch (InterruptedException e) {
            errorCount.incrementAndGet();
            Thread.currentThread().interrupt();
        }
    }

    private void processVersion4() {
        Thread workshop1 = new Thread(() -> {
            while (processedItems.get() < totalItemsToProcess) {
                synchronized (stockLock) {
                    if (inputStock.get() > 0 && intermediateStock.get() < totalItemsToProcess * 2) {
                        if (takeFromInputStock(1) && addToIntermediateStock(1)) {
                            // Workshop 1 processing complete
                        }
                    }
                }
                try {
                    Thread.sleep(10);
                } catch (InterruptedException e) {
                    errorCount.incrementAndGet();
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        Thread workshop2 = new Thread(() -> {
            while (processedItems.get() < totalItemsToProcess) {
                synchronized (stockLock) {
                    if (inputStock.get() > 0 && intermediateStock.get() < totalItemsToProcess * 2) {
                        if (takeFromInputStock(1) && addToIntermediateStock(1)) {
                            // Workshop 2 processing complete
                        }
                    }
                }
                try {
                    Thread.sleep(10);
                } catch (InterruptedException e) {
                    errorCount.incrementAndGet();
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        Thread workshop3 = new Thread(() -> {
            while (processedItems.get() < totalItemsToProcess) {
                synchronized (stockLock) {
                    if (intermediateStock.get() >= 2) {
                        if (takeFromIntermediateStock(2) && addToOutputStock(1)) {
                            // Workshop 3 combining complete
                        }
                    }
                }
                try {
                    Thread.sleep(15);
                } catch (InterruptedException e) {
                    errorCount.incrementAndGet();
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        workshop1.start();
        workshop2.start();
        workshop3.start();

        try {
            workshop1.join();
            workshop2.join();
            workshop3.join();
        } catch (InterruptedException e) {
            errorCount.incrementAndGet();
            Thread.currentThread().interrupt();
        }
    }

    public static class FactoryPerformance {
        private final int factoryVersion;
        private final long executionTimeMs;
        private final int processedItems;
        private final int errorCount;
        private final int remainingInputStock;
        private final int remainingIntermediateStock;
        private final int outputStock;
        private final int targetItems;
        private final double efficiency;

        public FactoryPerformance(int factoryVersion, long executionTimeMs, int processedItems, 
                                 int errorCount, int remainingInputStock, 
                                 int remainingIntermediateStock, int outputStock, int targetItems) {
            this.factoryVersion = factoryVersion;
            this.executionTimeMs = executionTimeMs;
            this.processedItems = processedItems;
            this.errorCount = errorCount;
            this.remainingInputStock = remainingInputStock;
            this.remainingIntermediateStock = remainingIntermediateStock;
            this.outputStock = outputStock;
            this.targetItems = targetItems;
            this.efficiency = targetItems > 0 ? (double) processedItems / targetItems * 100 : 0;
        }

        public int getFactoryVersion() {
            return factoryVersion;
        }

        public long getExecutionTimeMs() {
            return executionTimeMs;
        }

        public int getProcessedItems() {
            return processedItems;
        }

        public int getErrorCount() {
            return errorCount;
        }

        public int getRemainingInputStock() {
            return remainingInputStock;
        }

        public int getRemainingIntermediateStock() {
            return remainingIntermediateStock;
        }

        public int getOutputStock() {
            return outputStock;
        }

        public int getTargetItems() {
            return targetItems;
        }

        public double getEfficiency() {
            return efficiency;
        }

        public boolean isTargetAchieved() {
            return processedItems >= targetItems;
        }

        @Override
        public String toString() {
            return String.format(
                "Factory Performance Report (Version %d):\n" +
                "  Execution Time: %d ms\n" +
                "  Processed Items: %d/%d (%.1f%% efficiency)\n" +
                "  Target Achieved: %s\n" +
                "  Errors: %d\n" +
                "  Stock Levels:\n" +
                "    - Input: %d remaining\n" +
                "    - Intermediate: %d remaining\n" +
                "    - Output: %d produced\n",
                factoryVersion, executionTimeMs, processedItems, targetItems, efficiency,
                isTargetAchieved() ? "Yes" : "No", errorCount,
                remainingInputStock, remainingIntermediateStock, outputStock
            );
        }
    }

    public static void main(String[] args) {
        int initialStock = 100;
        int itemsToProcess = 75;

        for (int version = 1; version <= 4; version++) {
            EnhancedFactory factory = new EnhancedFactory(initialStock, itemsToProcess, version);
            FactoryPerformance performance = factory.runSimulation();
            System.out.println(performance);
            System.out.println("=".repeat(50));
        }
    }
}

