/**
 * Reranks items using an exact scoring function, keeping the top K items with highest exact scores.
 * Maintains approximate scores of reranked items to correctly determine the worst approximate score
 * among the final topK items selected by exact scores.
 * If no items meet the rerankFloor, the single item with highest approximate score is still reranked.
 *
 * @param topK the number of top items to keep in the reranked results
 * @param rerankScorer the scoring function to use for exact scoring/reranking
 * @param rerankFloor the minimum approximate score threshold for items to be considered for reranking
 * @param rerankedResults output container for the top K items after reranking (maps item ID to exact score)
 * @param unusedResults output container for items that don't make it to the top K (maps item ID to approximate score)
 * @return the worst (lowest) approximate score among the topK reranked items, or positive infinity if fewer than topK items are reranked
 */
public float rerank(int topK, ScoreFunction rerankScorer, float rerankFloor, 
                   java.util.Map<Integer, Float> rerankedResults, java.util.Map<Integer, Float> unusedResults) {
    // Clear output containers
    rerankedResults.clear();
    unusedResults.clear();

    // Use a priority queue as a min-heap to keep track of top K items by exact score
    java.util.PriorityQueue<Item> topKHeap = new java.util.PriorityQueue<>((a, b) -> Float.compare(a.exactScore, b.exactScore));

    // Track the approximate scores of all items that are reranked (have exact scores computed)
    java.util.Map<Integer, Float> rerankedApproxScores = new java.util.HashMap<>();

    // Track the item with highest approximate score (for fallback case)
    ItemWithApproxScore highestApproxItem = null;

    // Get all items with their approximate scores
    java.util.Map<Integer, Float> allItems = getAllItems();

    // First pass: filter by rerankFloor and find highest approximate score
    for (java.util.Map.Entry<Integer, Float> entry : allItems.entrySet()) {
        int itemId = entry.getKey();
        float approxScore = entry.getValue();

        // Track the item with highest approximate score
        if (highestApproxItem == null || approxScore > highestApproxItem.approxScore) {
            highestApproxItem = new ItemWithApproxScore(itemId, approxScore);
        }

        if (approxScore < rerankFloor) {
            // Below floor - will go to unused unless it's the fallback
            unusedResults.put(itemId, approxScore);
        } else {
            // Meets floor - candidate for reranking
            rerankedApproxScores.put(itemId, approxScore);
        }
    }

    // If no items meet the rerankFloor, promote the highest scoring item for reranking
    boolean usedFallback = false;
    if (rerankedApproxScores.isEmpty() && highestApproxItem != null) {
        // Remove the highest scoring item from unused if it was added
        unusedResults.remove(highestApproxItem.itemId);

        // Add the highest scoring item for reranking
        rerankedApproxScores.put(highestApproxItem.itemId, highestApproxItem.approxScore);
        usedFallback = true;
    }

    // Second pass: compute exact scores only for items in rerankedApproxScores
    for (java.util.Map.Entry<Integer, Float> entry : rerankedApproxScores.entrySet()) {
        int itemId = entry.getKey();
        float approxScore = entry.getValue();

        // Compute exact score
        float exactScore = rerankScorer.score(itemId);

        // Add to min-heap for top-K tracking
        topKHeap.offer(new Item(itemId, exactScore, approxScore));

        // If we exceed K items, remove the smallest exact score
        if (topKHeap.size() > topK) {
            topKHeap.poll();
        }
    }

    // Extract final topK items and populate rerankedResults
    java.util.List<Item> finalTopK = new java.util.ArrayList<>();
    while (!topKHeap.isEmpty()) {
        finalTopK.add(topKHeap.poll());
    }

    // Add items to rerankedResults in descending order of exact score
    for (int i = finalTopK.size() - 1; i >= 0; i--) {
        Item item = finalTopK.get(i);
        rerankedResults.put(item.itemId, item.exactScore);
    }

    // Move any reranked items that weren't in the final topK to unusedResults
    java.util.Set<Integer> inFinalTopK = rerankedResults.keySet();
    for (java.util.Map.Entry<Integer, Float> entry : rerankedApproxScores.entrySet()) {
        int itemId = entry.getKey();
        float approxScore = entry.getValue();
        if (!inFinalTopK.contains(itemId)) {
            unusedResults.put(itemId, approxScore);
        }
    }

    // Determine the worst (lowest) approximate score among the final topK reranked items
    float worstApproximateScore = Float.POSITIVE_INFINITY;

    if (!finalTopK.isEmpty()) {
        // Find the minimum approximate score among the final topK items
        worstApproximateScore = Float.MAX_VALUE;
        for (Item item : finalTopK) {
            if (item.approxScore < worstApproximateScore) {
                worstApproximateScore = item.approxScore;
            }
        }
    }

    return worstApproximateScore;
}

// Helper classes for internal use
private static class ItemWithApproxScore {
    final int itemId;
    final float approxScore;

    ItemWithApproxScore(int itemId, float approxScore) {
        this.itemId = itemId;
        this.approxScore = approxScore;
    }
}

private static class Item {
    final int itemId;
    final float exactScore;
    final float approxScore;

    Item(int itemId, float exactScore, float approxScore) {
        this.itemId = itemId;
        this.exactScore = exactScore;
        this.approxScore = approxScore;
    }
}

