class MinesweeperSolver {
    private char[][] map;
    private boolean[][] visited;
    private final int[] dirR = {-1, -1, -1, 0, 0, 1, 1, 1};
    private final int[] dirC = {-1, 0, 1, -1, 1, -1, 0, 1};

    private void dfsReveal(int i, int j) {
        if (visited[i][j]) {
            return;
        }
        visited[i][j] = true;

        for (int k = 0; k < 8; k++) {
            int ni = i + dirR[k];
            int nj = j + dirC[k];
            if (map[ni][nj] >= '1' && map[ni][nj] <= '8') {
                visited[ni][nj] = true;
            } else if (map[ni][nj] == '0' && !visited[ni][nj]) {
                dfsReveal(ni, nj);
            }
        }
    }

    public int solveMinesweeper(int boardSize, List<String> minePositions) {
        map = new char[boardSize + 2][boardSize + 2];
        visited = new boolean[boardSize + 2][boardSize + 2];

        for (int i = 0; i < map.length; i++) {
            for (int j = 0; j < map[0].length; j++) {
