            int c = Integer.parseInt(parts[1]);
            map[r][c] = '*';
        }

        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                if (map[i][j] != '*') {
                    int count = 0;
                    for (int k = 0; k < 8; k++) {
                        int ni = i + dirR[k];
                        int nj = j + dirC[k];
                        if (map[ni][nj] == '*') {
                            count++;
                        }
                    }
                    map[i][j] = (char) ('0' + count);
                }
            }
        }

        int clicks = 0;

        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                if (map[i][j] == '0' && !visited[i][j]) {
                    dfsReveal(i, j);
                    clicks++;
                }
            }
        }

        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                if (map[i][j] != '*' && !visited[i][j]) {
                    clicks++;
                }
            }
        }

        return clicks;
