        }

        public double getBandwidth() {
            return bandwidth;
        }
    }

    /**
     * Plan aggregates frequency assignments and channels. Provides methods to compute totals.
     */
    public static class Plan {
        private final List<FrequencyAssignment> assignments;
        private final List<Channel> channels;

        /**
         * Constructs a Plan from lists of assignments and channels.
         * The lists are copied to preserve immutability of the Plan instance.
         *
         * @param assignments list of FrequencyAssignment objects
         * @param channels    list of Channel objects
         */
        public Plan(List<FrequencyAssignment> assignments, List<Channel> channels) {
            this.assignments = assignments == null ? Collections.emptyList() : new ArrayList<>(assignments);
            this.channels = channels == null ? Collections.emptyList() : new ArrayList<>(channels);
        }

        public List<FrequencyAssignment> getAssignments() {
            return Collections.unmodifiableList(assignments);
        }

        public List<Channel> getChannels() {
            return Collections.unmodifiableList(channels);
        }

        /**
         * Sums the bandwidths required by all FrequencyAssignments in the plan.
         *
         * @return total required bandwidth (0.0 if none)
         */
        public double getTotalRequiredBandwidth() {
            double sum = 0.0;
            for (FrequencyAssignment a : assignments) {
                sum += a.getBandwidth();
            }
            return sum;
        }

        /**
         * Sums the bandwidths available across all Channels in the plan.
         *
         * @return total available bandwidth (0.0 if none)
         */
        public double getTotalAvailableBandwidth() {
            double sum = 0.0;
            for (Channel c : channels) {
                sum += c.getBandwidth();
            }
            return sum;
        }
    }

    /**
     * Creates a Plan by processing input arrays. Only entries with positive, finite bandwidths are included.
     * Invalid entries (non-positive or non-finite bandwidths, null channel ids) are ignored.
     *
     * For assignments, the number of elements processed is the minimum of assignFreqs.length and assignBandwidths.length.
     * For channels, the number of elements processed is the minimum of channelIds.length and channelBandwidths.length.
     *
     * @param assignFreqs       array of frequencies for assignments (may be null)
     * @param assignBandwidths  array of required bandwidths for assignments (may be null)
     * @param channelIds        array of channel identifiers (may be null)
     * @param channelBandwidths array of available bandwidths for channels (may be null)
     * @return constructed Plan containing only valid entries
     */
    public static Plan createPlan(double[] assignFreqs, double[] assignBandwidths, String[] channelIds, double[] channelBandwidths) {
        List<FrequencyAssignment> assignments = new ArrayList<>();
        List<Channel> channels = new ArrayList<>();

        if (assignFreqs != null && assignBandwidths != null) {
            int n = Math.min(assignFreqs.length, assignBandwidths.length);
            for (int i = 0; i < n; i++) {
                double bw = assignBandwidths[i];
                // Only accept positive finite bandwidths
                if (Double.isFinite(bw) && bw > 0.0) {
                    double freq = assignFreqs[i];
                    // constructor will validate bandwidth (positive) as well
                    assignments.add(new FrequencyAssignment(freq, bw));
                }
            }
        }

        if (channelIds != null && channelBandwidths != null) {
            int n = Math.min(channelIds.length, channelBandwidths.length);
            for (int i = 0; i < n; i++) {
                double bw = channelBandwidths[i];
                String id = channelIds[i];
                // Only accept positive finite bandwidths and non-null/non-empty ids
                if (id != null && !id.isEmpty() && Double.isFinite(bw) && bw > 0.0) {
                    // Channel constructor will validate id (non-null) and bandwidth (positive)
                    channels.add(new Channel(id, bw));
                }
            }
        }

        return new Plan(assignments, channels);
    }
}

