import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicInteger;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;

class TestSystemShutdownManager {

    @Test
    public void testGetAndSetAtomicBehavior() throws InterruptedException {
        Map<String, SystemShutdownManager.Service> services = new HashMap<>();
        services.put("service1", () -> {});

        SystemShutdownManager manager = new SystemShutdownManager(services, 1000, TimeUnit.MILLISECONDS);

        CountDownLatch latch = new CountDownLatch(2);
        AtomicInteger successCount = new AtomicInteger(0);

        // Create two threads that try to shutdown simultaneously
        Thread thread1 = new Thread(() -> {
            if (manager.shutdownAll()) {
                successCount.incrementAndGet();
            }
            latch.countDown();
        });

        Thread thread2 = new Thread(() -> {
            if (manager.shutdownAll()) {
                successCount.incrementAndGet();
            }
            latch.countDown();
        });

        thread1.start();
        thread2.start();

        latch.await();

        // Only one thread should succeed due to getAndSet(true) atomic operation
        assertEquals(1, successCount.get(), "Only one thread should successfully shutdown when using getAndSet(true)");
    }

    @Test
    public void testGetAndSetReturnsOriginalValue() {
        Map<String, SystemShutdownManager.Service> services = new HashMap<>();
        services.put("service1", () -> {});

        SystemShutdownManager manager = new SystemShutdownManager(services, 1000, TimeUnit.MILLISECONDS);

        // First call should succeed (getAndSet returns false, condition fails, proceeds)
        assertTrue(manager.shutdownAll(), "First shutdown call should succeed");

        // Second call should fail (getAndSet returns true, condition succeeds, returns false)
        assertFalse(manager.shutdownAll(), "Second shutdown call should fail due to getAndSet returning true");
    }

    @Test
    public void testTimeoutMessagePrinted() {
        // Capture System.out
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        PrintStream originalOut = System.out;
        System.setOut(new PrintStream(outputStream));

        try {
            Map<String, SystemShutdownManager.Service> services = new HashMap<>();
            services.put("slowService", () -> {
                try {
                    Thread.sleep(200); // Service takes 200ms
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });

            // Set very short timeout (50ms) to trigger timeout
            SystemShutdownManager manager = new SystemShutdownManager(services, 50, TimeUnit.MILLISECONDS);

            boolean result = manager.shutdownAll();

            assertFalse(result, "Shutdown should fail due to timeout");

            String output = outputStream.toString();
            assertTrue(output.contains("Shutdown timeout exceeded for service: slowService"), 
                      "Timeout message should be printed for the slow service");

        } finally {
            System.setOut(originalOut);
        }
    }
}

