        boolean usernameValid = USERNAME_PATTERN.matcher(username).matches();
        boolean passwordValid = PASSWORD_PATTERN.matcher(password).matches();

        // Determine overall authentication status
        boolean authenticated = usernameValid && passwordValid;

        // Choose appropriate message based on validation outcome
        String message;
        if (!usernameValid) {
            message = "Invalid username format";
        } else if (!passwordValid) {
            message = "Password doesn't meet complexity requirements";
        } else {
            message = "Authentication successful";
        }

        // Populate result map
        result.put("authenticated", authenticated);
        result.put("usernameValid", usernameValid);
        result.put("passwordValid", passwordValid);
        result.put("message", message);

