import java.util.*;
import java.text.*;

class EggDropSolver {
    /** Holds the results of the three algorithms and their execution times. */
    public static class Result {
        public final int dpResult;
        public final int mathResult;
        public final int binarySearchResult;
        public final long dpTime;
        public final long mathTime;
        public final long binarySearchTime;

        public Result(int dpResult, int mathResult, int binarySearchResult,
                      long dpTime, long mathTime, long binarySearchTime) {
            this.dpResult = dpResult;
            this.mathResult = mathResult;
            this.binarySearchResult = binarySearchResult;
            this.dpTime = dpTime;
            this.mathTime = mathTime;
            this.binarySearchTime = binarySearchTime;
        }
    }

    /** Public entry point – returns a Result object containing all three solutions. */
    public static Result solveEggDrop(int k, int n) {
        if (k <= 0) {
            throw new IllegalArgumentException("Number of eggs must be positive");
        }
        if (n <= 0) {
            throw new IllegalArgumentException("Number of floors must be positive");
        }

        long dpStart = System.nanoTime();
        int dpRes = solveDynamicProgramming(k, n);
        long dpEnd = System.nanoTime();

        long mathStart = System.nanoTime();
        int mathRes = solveMathematical(k, n);
        long mathEnd = System.nanoTime();

        long bsStart = System.nanoTime();
        int bsRes = solveBinarySearchWithMemoization(k, n);
        long bsEnd = System.nanoTime();

        return new Result(dpRes, mathRes, bsRes,
                          dpEnd - dpStart,
                          mathEnd - mathStart,
                          bsEnd - bsStart);
    }

    /* --------------------- Dynamic‑Programming solution --------------------- */
    private static int solveDynamicProgramming(int k, int n) {
        int[][] dp = new int[k + 1][n + 1];

        // Base cases
        for (int j = 1; j <= n; j++) dp[1][j] = j;          // 1 egg
        for (int i = 1; i <= k; i++) dp[i][1] = 1;          // 1 floor

        for (int i = 2; i <= k; i++) {
            for (int j = 2; j <= n; j++) {
                dp[i][j] = Integer.MAX_VALUE;
                for (int x = 1; x <= j; x++) {
                    int attempts = 1 + Math.max(dp[i - 1][x - 1], dp[i][j - x]);
                    if (attempts < dp[i][j]) dp[i][j] = attempts;
                }
            }
        }
        return dp[k][n];
    }

    /* --------------------- Mathematical (binomial‑coefficient) solution --------------------- */
    private static int solveMathematical(int k, int n) {
        for (int m = 1; m <= n; m++) {
            long total = 0;
            for (int i = 1; i <= k && i <= m; i++) {
                total += binomialCoefficient(m, i);
                if (total >= n) return m;
            }
        }
        return n;   // Fallback – should never be reached for valid inputs
    }

    /* --------------------- Binary‑search with memoization solution --------------------- */
    private static int solveBinarySearchWithMemoization(int k, int n) {
        Map<String, Integer> memo = new HashMap<>();
        return binarySearchHelper(k, n, memo);
    }

    private static int binarySearchHelper(int k, int n, Map<String, Integer> memo) {
        if (n == 0 || n == 1) return n;
        if (k == 1) return n;

        String key = k + "," + n;
        if (memo.containsKey(key)) return memo.get(key);

        int minAttempts = Integer.MAX_VALUE;
        int low = 1, high = n;

        while (low <= high) {
            int mid = low + (high - low) / 2;

            int breakCase   = binarySearchHelper(k - 1, mid - 1, memo);
            int noBreakCase = binarySearchHelper(k, n - mid, memo);

            int current = 1 + Math.max(breakCase, noBreakCase);

            if (breakCase > noBreakCase) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }

            if (current < minAttempts) minAttempts = current;
        }

        memo.put(key, minAttempts);
        return minAttempts;
    }

    /* --------------------- Helper: binomial coefficient --------------------- */
    private static long binomialCoefficient(int n, int k) {
        if (k > n || k < 0) return 0;
        if (k == 0 || k == n) return 1;
        k = Math.min(k, n - k);
        long result = 1;
        for (int i = 0; i < k; i++) {
            result = result * (n - i) / (i + 1);
        }
        return result;
    }
}

