class EggDropSolver {

    /** Result container holding both DP and mathematical solutions and their timings. */
    public static class Result {
        public final int dpResult;
        public final int mathResult;
        public final long dpTimeMillis;
        public final long mathTimeMillis;

        public Result(int dpResult, int mathResult, long dpTimeMillis, long mathTimeMillis) {
            this.dpResult = dpResult;
            this.mathResult = mathResult;
            this.dpTimeMillis = dpTimeMillis;
            this.mathTimeMillis = mathTimeMillis;
        }
    }

    /**
     * Computes the minimum number of attempts needed to find the critical floor
     * using both a dynamic‑programming approach and a mathematical binomial‑coefficient approach.
     *
     * @param k number of eggs (must be > 0)
     * @param n number of floors (must be > 0)
     * @return Result containing both solutions and their computation times
     * @throws IllegalArgumentException if k <= 0 or n <= 0
     */
    public static Result solveEggDrop(int k, int n) {
        if (k <= 0) {
            throw new IllegalArgumentException("Number of eggs must be positive");
        }
        if (n <= 0) {
            throw new IllegalArgumentException("Number of floors must be positive");
        }

        long dpStart = System.nanoTime();
        int dpResult = solveDP(k, n);
        long dpEnd = System.nanoTime();

        long mathStart = System.nanoTime();
        int mathResult = solveMath(k, n);
        long mathEnd = System.nanoTime();

        return new Result(dpResult, mathResult,
                (dpEnd - dpStart) / 1_000_000,
                (mathEnd - mathStart) / 1_000_000);
    }

    /** Dynamic‑programming implementation (O(k·n²)). */
    private static int solveDP(int k, int n) {
        int[][] dp = new int[k + 1][n + 1];

        // Base cases
        for (int j = 1; j <= n; j++) {
            dp[1][j] = j;          // one egg: linear search
        }
        for (int i = 1; i <= k; i++) {
            dp[i][1] = 1;          // one floor: one attempt
        }

        // DP recurrence
        for (int i = 2; i <= k; i++) {
            for (int j = 2; j <= n; j++) {
                int best = Integer.MAX_VALUE;
                for (int x = 1; x <= j; x++) {
                    int attempts = 1 + Math.max(dp[i - 1][x - 1], dp[i][j - x]);
                    if (attempts < best) {
                        best = attempts;
                    }
                }
                dp[i][j] = best;
            }
        }
        return dp[k][n];
    }

    /** Mathematical binomial‑coefficient implementation (O(k·m)). */
    private static int solveMath(int k, int n) {
        int moves = 0;
        long floorsTestable = 0;

        while (floorsTestable < n) {
            moves++;
            long binom = 1; // C(moves, 0)
            floorsTestable = 0;
            for (int i = 1; i <= k; i++) {
                // Compute C(moves, i) iteratively
                binom = binom * (moves - i + 1) / i;
                floorsTestable += binom;
                if (floorsTestable >= n) {
                    break;
                }
            }
        }
        return moves;
    }
}

