def task_func(json_str):
    # Load JSON string into a dictionary
    data_dict = json.loads(json_str)

    # Normalize the dictionary by doubling numerical values
    def is_numeric_string(s):
        """Check if a string represents a number (int or float)"""
        if isinstance(s, str):
            try:
                float(s)
                return True
            except ValueError:
                return False
        return False

    def convert_and_double_numeric_string(s):
        """Convert numeric string to appropriate number type and double it"""
        if '.' in s:
            return float(s) * 2
        else:
            return int(s) * 2

    def double_numerical_values(obj):
        if isinstance(obj, dict):
            return {key: double_numerical_values(value) for key, value in obj.items()}
        elif isinstance(obj, list):
            return [double_numerical_values(item) for item in obj]
        elif isinstance(obj, (int, float)):
            return obj * 2
        elif is_numeric_string(obj):
            return convert_and_double_numeric_string(obj)
        else:
            return obj

    normalized_dict = double_numerical_values(data_dict)

    # Create a Pandas DataFrame from the normalized dictionary
    df = pd.DataFrame(normalized_dict)

    return df

import java.util.*;

/**
 * Represents a category with an id, name and parent id.
 */
class Category {
    private long id;
    private String name;
    private long parentId;

    public Category(long id, String name, long parentId) {
        this.id = id;
        this.name = name;
        this.parentId = parentId;
    }

    public long getId() { return id; }
    public String getName() { return name; }
    public long getParentId() { return parentId; }

    public void setId(long id) { this.id = id; }
    public void setName(String name) { this.name = name; }
    public void setParentId(long parentId) { this.parentId = parentId; }
}

/**
 * Node used to build the category tree.
 */
class CategoryNode {
    private Category category;
    private List<CategoryNode> children = new ArrayList<>();

    public CategoryNode(Category category) {
        this.category = category;
    }

    public Category getCategory() { return category; }
    public List<CategoryNode> getChildren() { return children; }

    public void addChild(CategoryNode child) {
        children.add(child);
    }
}

/**
 * Result wrapper for the list of category trees.
 */
class CatResult {
    private List<CategoryNode> data;

    public CatResult(List<CategoryNode> data) {
        this.data = data;
    }

    public List<CategoryNode> getData() { return data; }
    public void setData(List<CategoryNode> data) { this.data = data; }
}

/**
 * Service that manages categories and builds the tree structure.
 */
class ItemCatService {
    // Stores all categories by id
    private Map<Long, Category> categoriesById = new HashMap<>();
    // Maps parent id to list of child categories
    private Map<Long, List<Category>> childrenByParentId = new HashMap<>();

    /**
     * Adds a new category.
     *
     * @param id       the unique id of the category
     * @param name     the name of the category
     * @param parentId the id of the parent category (0 for root)
     */
    public void addCategory(long id, String name, long parentId) {
        Category cat = new Category(id, name, parentId);
        categoriesById.put(id, cat);
        childrenByParentId.computeIfAbsent(parentId, k -> new ArrayList<>()).add(cat);
    }

    /**
     * Builds and returns the category tree.
     *
     * @return CatResult containing the root nodes of the tree
     */
    public CatResult getItemCatList() {
        if (categoriesById.isEmpty()) {
            return new CatResult(Collections.emptyList());
        }

        List<CategoryNode> roots = new ArrayList<>();
        List<Category> rootCategories = childrenByParentId.getOrDefault(0L, Collections.emptyList());
        for (Category rootCat : rootCategories) {
            CategoryNode rootNode = buildTree(rootCat);
            roots.add(rootNode);
        }
        return new CatResult(roots);
    }

    /**
     * Recursively builds a CategoryNode tree starting from the given category.
     *
     * @param cat the category to start from
     * @return the root node of the subtree
     */
    private CategoryNode buildTree(Category cat) {
        CategoryNode node = new CategoryNode(cat);
        List<Category> children = childrenByParentId.getOrDefault(cat.getId(), Collections.emptyList());
        for (Category child : children) {
            // Recursively process all descendants
            node.addChild(buildTree(child));
        }
        return node;
    }
}

