public class UserInfoManager {

    /** Simple regex for a 10‑digit phone number (e.g., "1234567890"). */
    private static final Pattern PHONE_PATTERN = Pattern.compile("^\\d{10}$");

    /** Represents a raw contact entry. */
    public static class PhoneContact {
        private final String name;
        private final String phoneNumber;

        public PhoneContact(String name, String phoneNumber) {
            this.name = name;
            this.phoneNumber = phoneNumber;
        }

        public String getName() { return name; }
        public String getPhoneNumber() { return phoneNumber; }

        @Override
        public String toString() {
            return "PhoneContact{name='" + name + '\'' +
                   ", phoneNumber='" + phoneNumber + '\'' + '}';
        }
    }

    /** Represents a validated user information entry. */
    public static class UserInfo {
        private final String fullName;
        private final String normalizedPhone;

        public UserInfo(String fullName, String normalizedPhone) {
            this.fullName = fullName;
            this.normalizedPhone = normalizedPhone;
        }

        public String getFullName() { return fullName; }
        public String getNormalizedPhone() { return normalizedPhone; }

        @Override
        public String toString() {
            return "UserInfo{fullName='" + fullName + '\'' +
                   ", normalizedPhone='" + normalizedPhone + '\'' + '}';
        }
    }

    /**
     * Processes contacts in batches of exactly 200.
     *
     * @param contacts the raw contacts to be processed; may be empty but not {@code null}
     * @return a map with two entries:
     *         <ul>
     *           <li>"processed" → {@code List<UserInfo>} of all successfully converted contacts</li>
     *           <li>"batchesProcessed" → {@code Integer} count of full 200‑size batches handled</li>
     *         </ul>
     */
    public Map<String, Object> processContacts(List<PhoneContact> contacts) {
        if (contacts == null) {
            throw new IllegalArgumentException("Contact list cannot be null");
        }

        List<UserInfo> processed = new ArrayList<>();
        int batchesProcessed = 0;
        final int BATCH_SIZE = 200;

        // Only full batches of exactly 200 are processed.
        for (int start = 0; start + BATCH_SIZE <= contacts.size(); start += BATCH_SIZE) {
            List<PhoneContact> batch = contacts.subList(start, start + BATCH_SIZE);
            for (PhoneContact contact : batch) {
                if (isValidContact(contact)) {
                    UserInfo userInfo = new UserInfo(
                            contact.getName().trim(),
                            contact.getPhoneNumber().trim()
                    );
                    processed.add(userInfo);
                }
            }
            batchesProcessed++;
        }

        Map<String, Object> result = new HashMap<>();
        result.put("processed", processed);
        result.put("batchesProcessed", batchesProcessed);
