    void testSendMessageAsyncThrowsIllegalStateExceptionWhenNotConnected() {
        EnhancedWebSocketClient client = new EnhancedWebSocketClient("ws://example.com");

        CompletableFuture<Void> result = client.sendMessageAsync("test message");

        assertTrue(result.isCompletedExceptionally());

        ExecutionException exception = assertThrows(ExecutionException.class, () -> {
            result.get();
        });

        assertTrue(exception.getCause() instanceof IllegalStateException);
        assertEquals("Connection is not established or is closed", exception.getCause().getMessage());
    }

    @Test
    void testSendMessageAsyncThrowsIllegalStateExceptionWhenConnectionClosed() throws Exception {
        EnhancedWebSocketClient client = new EnhancedWebSocketClient("ws://example.com");

        // First connect
        client.connectAsync().get();

        // Then close the connection
        client.closeAsync().get();

        // Now try to send a message
        CompletableFuture<Void> result = client.sendMessageAsync("test message");

        assertTrue(result.isCompletedExceptionally());

        ExecutionException exception = assertThrows(ExecutionException.class, () -> {
            result.get();
        });

        assertTrue(exception.getCause() instanceof IllegalStateException);
        assertEquals("Connection is not established or is closed", exception.getCause().getMessage());
