/**
 * A simple container that keeps parallel {@code int[]} and {@code float[]} arrays
 * sorted by the score (ascending).  The class demonstrates the required
 * {@code insertSorted} method together with the helper methods described in the
 * problem statement.
 */
public class SortedNodeArray {
    /** Holds the node identifiers. */
    private int[] nodes;
    /** Holds the scores associated with each node. */
    private float[] scores;
    /** Number of valid entries currently stored. */
    private int size;

    /** Creates an empty structure with an initial capacity. */
    public SortedNodeArray() {
        this.nodes = new int[4];
        this.scores = new float[4];
        this.size = 0;
    }

    /**
     * Inserts {@code newNode} with {@code newScore} while preserving the ascending
     * order of {@code scores}.  If a node with the same score already exists the
     * insertion is ignored and {@code -1} is returned.
     *
     * @param newNode  the node identifier to insert
     * @param newScore the score that determines the ordering
     * @return the index at which the node was inserted, or {@code -1} if a node
     *         with the same score already exists.
     */
    public int insertSorted(int newNode, float newScore) {
        // 1️⃣ Find where the new element should go.
        int ip = insertionPoint(newNode, newScore);
        if (ip == -1) {                     // duplicate score → ignore
            return -1;
        }

        // 2️⃣ Ensure there is room for the new element.
        if (size == nodes.length) {
            growArrays();
        }

        // 3️⃣ Perform the actual shift‑and‑insert.
        insertInternal(ip, newNode, newScore);
        return ip;
    }

    /**
     * Determines the index at which {@code newNode}/{@code newScore} should be
     * inserted to keep the array sorted.  If a score equal to {@code newScore}
     * already exists, {@code -1} is returned.
     *
     * @return the insertion index, or {@code -1} if the score already exists.
     */
    private int insertionPoint(int newNode, float newScore) {
        // Binary search for the first element whose score is greater than newScore.
        int lo = 0, hi = size;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (scores[mid] <= newScore) {
                lo = mid + 1;               // move right
            } else {
                hi = mid;                   // stay left
            }
        }
        // 'lo' is the first position where score > newScore.
        // Check whether an equal score already exists just before or after.
        if (lo > 0 && Float.compare(scores[lo - 1], newScore) == 0) {
            return -1;                      // duplicate score on the left side
        }
        if (lo < size && Float.compare(scores[lo], newScore) == 0) {
            return -1;                      // duplicate score on the right side
        }
        return lo;                          // valid insertion point
    }

    /**
     * Shifts the internal arrays to make room at {@code insertionPoint} and
     * stores {@code newNode}/{@code newScore} there.
     *
     * @param insertionPoint the index where the new element will be placed
     * @param newNode        the node identifier to insert
     * @param newScore       the associated score
     */
    private void insertInternal(int insertionPoint, int newNode, float newScore) {
        // Shift elements to the right, if necessary.
        if (insertionPoint < size) {
            System.arraycopy(nodes, insertionPoint, nodes, insertionPoint + 1,
                             size - insertionPoint);
            System.arraycopy(scores, insertionPoint, scores, insertionPoint + 1,
                             size - insertionPoint);
        }
        // Store the new values.
        nodes[insertionPoint] = newNode;
        scores[insertionPoint] = newScore;
        size++;
    }

    /** Doubles the capacity of the internal arrays. */
    private void growArrays() {
        int newCap = Math.max(4, nodes.length << 1);
        nodes = java.util.Arrays.copyOf(nodes, newCap);
        scores = java.util.Arrays.copyOf(scores, newCap);
    }

    // -------------------------------------------------------------------------
    // Utility methods for testing / demonstration (not required by the task)
    // -------------------------------------------------------------------------

    /** Returns the current number of stored elements. */
    public int size() {
        return size;
    }

    /** Returns the node identifier at the given index. */
    public int getNode(int index) {
        if (index < 0 || index >= size) throw new IndexOutOfBoundsException();
        return nodes[index];
    }

    /** Returns the score at the given index. */
    public float getScore(int index) {
        if (index < 0 || index >= size) throw new IndexOutOfBoundsException();
        return scores[index];
    }
}

