                throw new IllegalStateException("Cannot compute centroid of empty vector set");
            }

            // Get the first vector to determine dimension
            VectorFloat<?> firstVector = ravv.getVector(0);
            int dimension = firstVector.length();

            // Initialize sum array
            float[] sum = new float[dimension];

            // Sum all vectors
            for (int i = 0; i < vectorCount; i++) {
                VectorFloat<?> vector = ravv.getVector(i);
                for (int j = 0; j < dimension; j++) {
                    sum[j] += vector.get(j);
