 *
 * @param <T> the type of items to paginate
 */
public class PaginationService<T> {

    /**
     * Paginates the given list according to the supplied page number and rows per page.
     * <p>
     * The method optionally filters the list (case‑insensitive) when {@code key} is
     * non‑null/non‑empty, then optionally sorts the filtered list by the field named
     * {@code sortBy} (ascending or descending) when {@code sortBy} is non‑null/non‑empty.
     *
     * @param items       the full list of items (must not be {@code null})
     * @param page        the page number to retrieve (1‑based)
     * @param rowsPerPage the number of items per page (must be positive)
     * @param key         optional filter keyword; may be {@code null} or empty for no filtering
     * @param sortBy      optional field name to sort by; may be {@code null} or empty for no sorting
     * @param ascending   {@code true} for ascending order, {@code false} for descending
     * @return a {@link PaginatedResult} containing the items for the requested page and the total item count
     */
    public PaginatedResult<T> paginate(
            List<T> items,
            int page,
            int rowsPerPage,
            String key,
            String sortBy,
            boolean ascending) {

        if (items == null) {
            throw new IllegalArgumentException("Items list cannot be null");
        }
        if (page < 1 || rowsPerPage < 1) {
            // Invalid pagination parameters – return an empty result but keep the total count of the (filtered) list
            List<T> filtered = filterItems(items, key);
            return new PaginatedResult<>(Collections.emptyList(), filtered.size());
        }

        // 1️⃣ Defensive copy + filter
        List<T> processed = filterItems(items, key); // always a new list

        // 2️⃣ Sort (if required)
        if (sortBy != null && !sortBy.isEmpty()) {
            processed = sortItems(processed, sortBy, ascending);
        }

        // 3️⃣ Paginate
        int total = processed.size();
        int startIndex = (page - 1) * rowsPerPage;

        // When the requested page is beyond the available data, return an empty list but the correct total.
        if (startIndex >= total) {
            return new PaginatedResult<>(Collections.emptyList(), total);
        }

        int endIndex = Math.min(startIndex + rowsPerPage, total);
        List<T> pageSlice = processed.subList(startIndex, endIndex);
        // Defensive copy of the slice so the internal list cannot be altered from outside.
        List<T> pageItems = new ArrayList<>(pageSlice);

        return new PaginatedResult<>(pageItems, total);
    }

    /**
