def chunk_ranges(input_size, chunk_size, input_offset=0, overlap_size=0, align=False):
    if input_size <= input_offset:
        return
    if chunk_size <= 0:
        raise ValueError("chunk_size must be positive")
    if overlap_size < 0:
        raise ValueError("overlap_size must be non-negative")
    if overlap_size >= chunk_size:
        # Cannot have meaningful overlap for multiple chunks
        yield (input_offset, min(input_offset + chunk_size, input_size))
        return

    if not align:
        start = input_offset
        while start < input_size:
            end = start + chunk_size
            if end > input_size:
                end = input_size
            yield (start, end)
            if end == input_size:
                break
            start = end - overlap_size
    else:
        chunks = []
        end = input_size
        while end > input_offset:
            start = end - chunk_size
            if start < input_offset:
                start = input_offset
            chunks.append((start, end))
            next_end = start + overlap_size
            if next_end >= end:
                break
            end = next_end
        # Yield chunks in increasing order (from first to last)
