package com.example.mergeutils;

import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.stream.Collectors;

/**
 * Utility class providing a generic merge method that merges non-null properties from a source object
 * into a target object using JSON property names defined by @JsonProperty.
 */
public final class MergeUtils {

    // Cache of JSON property names per class to avoid repeated reflection
    private static final ConcurrentMap<Class<?>, List<String>> REQUEST_FIELD_NAMES_PER_CLASS = new ConcurrentHashMap<>();

    // Shared Jackson ObjectMapper for conversions
    private static final ObjectMapper MAPPER = new ObjectMapper();

    private MergeUtils() {
        // no instances
    }

    /**
     * Merge non-null properties from source into target using JSON property names (@JsonProperty).
     * If acceptedFieldNames is provided, only JSON properties present both on the class and in that list
     * will be considered. Otherwise, the @JsonProperty annotations on the class determine valid fields.
     *
     * The result is returned as an instance of the specified class constructed from the merged data.
     *
     * @param source              source object (may be null)
     * @param target              target object (may be null)
     * @param clazz               target class type
     * @param acceptedFieldNames  optional list of accepted JSON property names to restrict the merge
     * @param <T>                 type parameter of the target class
     * @return merged instance of clazz
     * @throws IllegalArgumentException if the resulting list of JSON property fields for the class is empty
     * @throws NullPointerException     if clazz is null
     */
    public static <T> T merge(Object source, Object target, Class<T> clazz, List<String> acceptedFieldNames) {
        Objects.requireNonNull(clazz, "clazz must not be null");

        // Load or compute the JSON property names for this class in a thread-safe manner
        List<String> classJsonProps = REQUEST_FIELD_NAMES_PER_CLASS.computeIfAbsent(clazz, MergeUtils::getJsonPropertyValues);

        // Determine which field names to consider: intersection if acceptedFieldNames provided, otherwise all class props
        List<String> requestFieldNames;
        if (acceptedFieldNames == null || acceptedFieldNames.isEmpty()) {
            requestFieldNames = classJsonProps;
        } else {
            // intersect while preserving order from acceptedFieldNames
            Set<String> classSet = new HashSet<>(classJsonProps);
            requestFieldNames = acceptedFieldNames.stream()
                    .filter(classSet::contains)
                    .distinct()
                    .collect(Collectors.toList());
        }

        if (requestFieldNames == null || requestFieldNames.isEmpty()) {
            throw new IllegalArgumentException("No @JsonProperty fields found in the class " + clazz.getName());
        }

        Map<String, Object> sourceMap = objectToMapOrEmpty(source);
        Map<String, Object> targetMap = objectToMapOrEmpty(target);

        // Merge: for each entry in sourceMap with non-null value and allowed name, put into targetMap
        for (Map.Entry<String, Object> e : sourceMap.entrySet()) {
            String key = e.getKey();
            Object value = e.getValue();
            if (value != null && requestFieldNames.contains(key)) {
                targetMap.put(key, value);
            }
        }

        // Remove any keys from targetMap that are not in the allowed list (prevent unintended properties)
        targetMap.keySet().removeIf(k -> !requestFieldNames.contains(k));

        // Convert the merged map back to the desired class instance
        return mapToClass(targetMap, clazz);
    }

    // Helper: convert object to map, returning empty map if null
    private static Map<String, Object> objectToMapOrEmpty(Object obj) {
        if (obj == null) {
            return new LinkedHashMap<>();
        }
        if (obj instanceof Map) {
            //noinspection unchecked
            return new LinkedHashMap<>((Map<String, Object>) obj);
        }
        return objectToMap(obj);
    }

    // Convert arbitrary object to Map<String, Object> using Jackson
    private static Map<String, Object> objectToMap(Object obj) {
        if (obj == null) {
            return new LinkedHashMap<>();
        }
        return MAPPER.convertValue(obj, new TypeReference<Map<String, Object>>() {});
    }

    // Convert map to class instance using Jackson
    private static <T> T mapToClass(Map<String, Object> map, Class<T> clazz) {
        if (map == null) {
            map = Collections.emptyMap();
        }
        return MAPPER.convertValue(map, clazz);
    }

    // Reflectively gather JSON property names from @JsonProperty annotations on fields and methods
    private static List<String> getJsonPropertyValues(Class<?> clazz) {
        if (clazz == null) {
            return Collections.emptyList();
        }

        // Use LinkedHashSet to preserve discovery order and avoid duplicates
        Set<String> props = new LinkedHashSet<>();

        // Fields: include only those annotated with @JsonProperty
        for (Field field : getAllFields(clazz)) {
            JsonProperty ann = field.getAnnotation(JsonProperty.class);
            if (ann != null) {
                String name = ann.value();
                if (name == null || name.isEmpty()) {
                    name = field.getName();
                }
                props.add(name);
            }
        }

        // Methods: include annotated getters/setters
        for (Method method : clazz.getMethods()) {
            JsonProperty ann = method.getAnnotation(JsonProperty.class);
            if (ann != null) {
                String name = ann.value();
                if (name == null || name.isEmpty()) {
                    name = derivePropertyNameFromAccessor(method.getName());
                }
                if (name != null && !name.isEmpty()) {
                    props.add(name);
                }
            }
        }

        return new ArrayList<>(props);
    }

    // Gather all declared fields from class hierarchy (excluding Object.class)
    private static List<Field> getAllFields(Class<?> clazz) {
        List<Field> fields = new ArrayList<>();
        Class<?> current = clazz;
        while (current != null && current != Object.class) {
            Field[] declared = current.getDeclaredFields();
            Collections.addAll(fields, declared);
            current = current.getSuperclass();
        }
        return fields;
    }

    // Derive property name from accessor method name (getXxx -> xxx, isXxx -> xxx)
    private static String derivePropertyNameFromAccessor(String methodName) {
        if (methodName == null || methodName.isEmpty()) {
            return methodName;
        }
        if (methodName.startsWith("get") && methodName.length() > 3) {
            return decapitalize(methodName.substring(3));
        }
        if (methodName.startsWith("is") && methodName.length() > 2) {
            return decapitalize(methodName.substring(2));
        }
        // Fallback to the method name itself
        return methodName;
    }

    // Decapitalize (similar to Introspector.decapitalize) but simple implementation
    private static String decapitalize(String str) {
        if (str == null || str.isEmpty()) {
            return str;
        }
        if (str.length() > 1 && Character.isUpperCase(str.charAt(1)) && Character.isUpperCase(str.charAt(0))) {
            return str;
        }
        char[] chars = str.toCharArray();
        chars[0] = Character.toLowerCase(chars[0]);
        return new String(chars);
    }
}

