import org.springframework.beans.BeanWrapperImpl;
import java.beans.Introspector;
import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.Set;

public class BeanUtils {
    public static <I, S extends I, T extends I> T mergeBeans(S source, T target, Class<I> sourceInterfaceClazz, boolean overrideNonNullTargetValues) {
        if (source == null) {
            throw new IllegalArgumentException("Source object must not be null");
        }
        if (target == null) {
            throw new IllegalArgumentException("Target object must not be null");
        }

        BeanWrapper sourceWrapper = new BeanWrapperImpl(source);
        BeanWrapper targetWrapper = new BeanWrapperImpl(target);

        Set<String> propertyNames = new HashSet<>();
        for (Method method : sourceInterfaceClazz.getMethods()) {
            if (method.getParameterCount() != 0) continue;
            String methodName = method.getName();
            if (methodName.startsWith("get") && methodName.length() > 3) {
                String propName = Introspector.decapitalize(methodName.substring(3));
                propertyNames.add(propName);
            } else if (methodName.startsWith("is") && methodName.length() > 2) {
                Class<?> returnType = method.getReturnType();
                if (returnType == boolean.class || returnType == Boolean.class) {
                    String propName = Introspector.decapitalize(methodName.substring(2));
                    propertyNames.add(propName);
                }
            }
        }

        for (String propName : propertyNames) {
            if (sourceWrapper.isReadableProperty(propName)) {
                Object value = sourceWrapper.getPropertyValue(propName);
                if (value != null) {
                    Object targetValue = targetWrapper.getPropertyValue(propName);
                    if (overrideNonNullTargetValues || targetValue == null) {
                        if (targetWrapper.isWritableProperty(propName)) {
                            targetWrapper.setPropertyValue(propName, value);
                        }
                    }
                }
            }
        }

        return target;
    }
}

