        return new Statistics(totalEntries, maxAccessKey, typeDistribution, estimatedMemory);
    }

    /** Returns all keys that store values of a specific type. */
    public List<String> findKeysByType(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type must not be null");
        }
        List<String> result = new ArrayList<>();
        for (Map.Entry<String, Object> e : store.entrySet()) {
            if (e.getValue() != null && e.getValue().getClass() == type) {
                result.add(e.getKey());
            }
        }
        return result;
    }

    /** Removes all data from the store. */
    public void clear() {
        store.clear();
        accessCounts.clear();
        lastAccessTimes.clear();
        typeCounts.clear();
    }

    /** Statistics data holder. */
    public static class Statistics {
        private final int totalEntries;
        private final String keyWithMaxAccess;
        private final Map<Class<?>, Integer> typeDistribution;
        private final long estimatedMemoryUsageBytes;

        public Statistics(int totalEntries, String keyWithMaxAccess,
                          Map<Class<?>, Integer> typeDistribution,
