import java.util.*;

class TwoSatSolver {
    private Set<Integer> variables;
    private Map<Integer, List<Integer>> graph;
    private Map<Integer, List<Integer>> reverseGraph;
    private Map<Integer, Integer> finishingTimes;
    private Set<Integer> visited;

    public TwoSatSolver() {
        variables = new HashSet<>();
        graph = new HashMap<>();
        reverseGraph = new HashMap<>();
        finishingTimes = new HashMap<>();
        visited = new HashSet<>();
    }

    public void addClause(int a, int b) {
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        // Add implication edges: (-a → b) and (-b → a)
        addImplication(-a, b);
        addImplication(-b, a);
    }

    private void addImplication(int from, int to) {
        if (!graph.containsKey(from)) {
            graph.put(from, new ArrayList<>());
        }
        graph.get(from).add(to);

        // Also add to reverse graph
        if (!reverseGraph.containsKey(to)) {
            reverseGraph.put(to, new ArrayList<>());
        }
        reverseGraph.get(to).add(from);
    }

    public boolean isSatisfiable() {
        // First pass: DFS on reverse graph to compute finishing times
        finishingTimes.clear();
        visited.clear();

        for (int var : variables) {
            int positive = var;
            int negative = -var;

            if (!visited.contains(positive)) {
                dfsReverse(positive);
            }
            if (!visited.contains(negative)) {
                dfsReverse(negative);
            }
        }

        return true;
    }

    private void dfsReverse(int node) {
        Stack<Integer> stack = new Stack<>();
        stack.push(node);
        visited.add(node);

        while (!stack.isEmpty()) {
            int current = stack.pop();

            for (int neighbor : reverseGraph.getOrDefault(current, Collections.emptyList())) {
                if (!visited.contains(neighbor)) {
                    visited.add(neighbor);
                    stack.push(neighbor);
                }
            }

            finishingTimes.put(current, finishingTimes.size() + 1);
        }
    }
}

