<T, S extends T> T mergeBeans(S source, T target, Class<T> sourceInterfaceClazz, boolean overrideNonNullTargetValues) {
    Assert.notNull(sourceInterfaceClazz, "Source interface class must not be null");
    Assert.notNull(source, "Source object must not be null");
    Assert.notNull(target, "Target object must not be null");

    BeanWrapper sourceWrapper = new BeanWrapperImpl(source);
    BeanWrapper targetWrapper = new BeanWrapperImpl(target);

    // Get all getter methods from the interface
    List<String> propertyNames = new ArrayList<>();
    for (Method method : sourceInterfaceClazz.getMethods()) {
        if (isGetterMethod(method)) {
            String propertyName = extractPropertyName(method.getName());
            propertyNames.add(propertyName);
        }
    }

    // Copy non-null properties from source to target
    for (String propertyName : propertyNames) {
        try {
            // Skip class property
            if ("class".equals(propertyName)) {
                continue;
            }

            PropertyDescriptor sourcePd = sourceWrapper.getPropertyDescriptor(propertyName);
            PropertyDescriptor targetPd = targetWrapper.getPropertyDescriptor(propertyName);

            if (sourcePd != null && targetPd != null && targetPd.getWriteMethod() != null) {
                Object sourceValue = sourceWrapper.getPropertyValue(propertyName);
                Object targetValue = targetWrapper.getPropertyValue(propertyName);

                // Only copy if source value is not null
                if (sourceValue != null) {
                    // If override is allowed, or if target value is null, then set the value
                    if (overrideNonNullTargetValues || targetValue == null) {
                        targetWrapper.setPropertyValue(propertyName, sourceValue);
                    }
                }
            }
        } catch (Exception e) {
            // Ignore properties that can't be copied
            continue;
        }
    }

    return target;
}

private boolean isGetterMethod(Method method) {
    String name = method.getName();
    // Must return something (not void) and have no parameters
    if (method.getReturnType() == void.class || method.getParameterCount() != 0) {
        return false;
    }

    // Check for standard getter pattern: getXXX() or isXXX() for booleans
    if (name.startsWith("get") && name.length() > 3) {
        return true;
    }
    if (name.startsWith("is") && name.length() > 2) {
        Class<?> returnType = method.getReturnType();
        return returnType == boolean.class || returnType == Boolean.class;
    }

    return false;
}

private String extractPropertyName(String methodName) {
    if (methodName.startsWith("get") || methodName.startsWith("set")) {
        return Introspector.decapitalize(methodName.substring(3));
    } else if (methodName.startsWith("is")) {
        return Introspector.decapitalize(methodName.substring(2));
    }
    return Introspector.decapitalize(methodName);
}

