    """
    Recursively iterates over all items in a dictionary and yields each key-value pair.

    Parameters
    ----------
    dictionary : dict
        The dictionary to iterate over
    manually_sorted_keys : list, optional
        A list of keys to sort by. If provided, these keys will be yielded first.

    Yields
    ------
    tuple
        A tuple of (key, value) pairs where key is the flattened path and value is the value
    """
    if manually_sorted_keys is None:
        manually_sorted_keys = []

    # First yield the manually sorted keys
    for key in manually_sorted_keys:
        if key in dictionary:
            value = dictionary[key]
            if isinstance(value, collections.abc.Mapping):
                for k, v in iterate_flattened_separately(value):
                    yield join_paths(key, k), v
            else:
                yield key, value

    # Then yield the rest of the keys
    for key, value in dictionary.items():
        if key in manually_sorted_keys:
            continue
        if isinstance(value, collections.abc.Mapping):
            for k, v in iterate_flattened_separately(value):
                yield join_paths(key, k), v
        else:
            yield key, value

