public class ScenarioAnalyzer {

    /** Simple tree node representation. */
    public static class Node {
        private final String name;
        private final List<Node> children = new ArrayList<>();

        public Node(String name) {
            this.name = Objects.requireNonNull(name);
        }

        public String getName() {
            return name;
        }

        public List<Node> getChildren() {
            return children;
        }

        public void addChild(Node child) {
            children.add(Objects.requireNonNull(child));
        }
    }

    /**
     * Traverses the tree rooted at {@code root} in breadth‑first order,
     * assigning consecutive integer indices starting at 0.
     *
     * @param root the root of the scenario tree; may be {@code null}
     * @return a map with a single entry {@code "nodeIndices"} that maps node
     *         names to their assigned indices
     */
    public Map<String, Object> analyzeScenario(Node root) {
        Map<String, Integer> nodeIndices = new LinkedHashMap<>(); // preserve order
        if (root != null) {
            Queue<Node> queue = new ArrayDeque<>();
            queue.add(root);
            int index = 0;

            while (!queue.isEmpty()) {
                Node current = queue.poll();
                nodeIndices.put(current.getName(), index++);
