@Test
public void testInsertDiverseConcurrent() {
  // set up BSP
  var sf = VectorSimilarityFunction.DOT_PRODUCT;
  var vectors = new TestVectorGraph.CircularFloatVectorValues(10);
  var natural = new NodeArray(10);
  var concurrent = new NodeArray(10);
  var bsp = BuildScoreProvider.randomAccessScoreProvider(vectors, sf);

  // Test search score provider for a given vector with exact similarity comparisons
  var queryVector = vectors.getVector(0);
  var searchProvider = bsp.searchProviderFor(queryVector);

  // Test that the search provider uses exact similarity function
  assert bsp.isExact();

  // Test parallel execution with separate thread-local copies
  var threads = new Thread[2];
  var success = new boolean[2];

  for (int t = 0; t < 2; t++) {
    final int threadId = t;
    threads[t] = new Thread(() -> {
      try {
        var threadSearchProvider = bsp.searchProviderFor(queryVector);
        success[threadId] = (threadSearchProvider != null);
      } catch (Exception e) {
        success[threadId] = false;
      }
    });
  }

  for (Thread thread : threads) {
    thread.start();
  }

  for (Thread thread : threads) {
    try {
      thread.join();
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
    }
  }

  // Verify all threads successfully created search providers
  for (boolean result : success) {
    assert result;
  }

  // Test the original functionality still works
  IntStream.range(0, 7)
      .forEach(i -> natural.insertSorted(i, scoreBetween(bsp, 7, i)));
  IntStream.range(8, 10)
      .forEach(
          i -> concurrent.insertSorted(i, scoreBetween(bsp, 7, i)));

  var cnm = new ConcurrentNeighborMap(new VamanaDiversityProvider(bsp, 1.0f), 10, 10);
  cnm.addNode(7);
  var neighbors = cnm.insertDiverse(7, NodeArray.merge(natural, concurrent));
  assertEquals(2, neighbors.size());
  assert neighbors.contains(8);
  assert neighbors.contains(6);
  validateSortedByScore(neighbors);
}
